import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import type { ChatMessage, User } from '../types.js';

export const MAX_MESSAGE_LENGTH = 2000;
export const CHAT_HISTORY_LIMIT = 100;

function dbPath(groupId: string): string {
  // IDs are generated by groups.ts; keep paths confined to the chat directory.
  if (!/^[a-zA-Z0-9_-]+$/.test(groupId)) throw new Error('Invalid group ID.');
  return path.join(process.cwd(), 'data', 'chat', groupId + '.json');
}

function readMessages(groupId: string): ChatMessage[] {
  const file = dbPath(groupId);
  if (!fs.existsSync(file)) return [];
  return JSON.parse(fs.readFileSync(file, 'utf-8'));
}

export function recentMessages(groupId: string): ChatMessage[] {
  return readMessages(groupId).slice(-CHAT_HISTORY_LIMIT);
}

export function appendMessage(groupId: string, author: User, text: unknown): ChatMessage {
  if (typeof text !== 'string' || !text.trim()) {
    throw new Error('Enter a message.');
  }
  if (text.length > MAX_MESSAGE_LENGTH) {
    throw new Error(`Messages must be ${MAX_MESSAGE_LENGTH} characters or fewer.`);
  }
  const message: ChatMessage = {
    id: crypto.randomUUID(),
    groupId,
    authorId: author.id,
    authorName: author.displayName || author.email,
    text: text.trim(),
    createdAt: new Date().toISOString(),
  };
  const messages = readMessages(groupId);
  messages.push(message);
  const file = dbPath(groupId);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  // Replace atomically so an interrupted write does not truncate the history.
  const temporary = file + '.tmp';
  fs.writeFileSync(temporary, JSON.stringify(messages, null, 2));
  fs.renameSync(temporary, file);
  return message;
}
